begin;
select no_plan();
select has_function('public','confirm_route_load',array['uuid','integer','uuid']);
insert into auth.users(id) values('71000000-0000-0000-0000-000000000001'),('71000000-0000-0000-0000-000000000002');
insert into public.profiles values('71000000-0000-0000-0000-000000000001','owner'),('71000000-0000-0000-0000-000000000002','driver');
insert into public.vehicles(id,name) values('71000000-0000-0000-0000-000000000010','Veículo fictício entrega');
insert into public.customers(id,name,address,weekday,position) values('71000000-0000-0000-0000-000000000020','Cliente fictício entrega','Rua fictícia',2,1);
insert into public.route_runs(id,template_id,service_date,driver_id,vehicle_id) values('71000000-0000-0000-0000-000000000030','50000000-0000-0000-0000-000000000002','2091-01-02','71000000-0000-0000-0000-000000000002','71000000-0000-0000-0000-000000000010');
insert into public.weekly_orders(id,customer_id,route_id,delivery_date,customer_name,customer_address) values('71000000-0000-0000-0000-000000000040','71000000-0000-0000-0000-000000000020','71000000-0000-0000-0000-000000000030','2091-01-02','Cliente fictício entrega','Rua fictícia');
insert into public.weekly_order_items values('71000000-0000-0000-0000-000000000040','30000000-0000-0000-0000-000000000030',30,1,3300);
insert into public.route_stops(id,route_id,order_id,kind,position,name) values('71000000-0000-0000-0000-000000000050','71000000-0000-0000-0000-000000000030','71000000-0000-0000-0000-000000000040','customer',1,'Cliente fictício entrega');
select set_config('request.jwt.claim.sub','71000000-0000-0000-0000-000000000001',true);
set local role authenticated;
select public.record_stock_event('{"kind":"purchase","location":"farm","eggs":300,"costCents":30000,"effectiveAt":"2026-10-29T00:00:00Z"}',gen_random_uuid());
select throws_ok($$select public.start_route('71000000-0000-0000-0000-000000000030',1,100,gen_random_uuid())$$,'PT409','LOAD_REQUIRED','entrega exige carga');
select is(public.confirm_route_load('71000000-0000-0000-0000-000000000030',1,'72000000-0000-0000-0000-000000000001')->>'status','ready','carga deixa pronta');
select is(public.confirm_route_load('71000000-0000-0000-0000-000000000030',1,'72000000-0000-0000-0000-000000000001')->>'status','ready','replay estável');
select is((select eggs from public.stock_balances where location='farm'),270,'carga única');
select throws_ok($$select public.save_weekly_order('71000000-0000-0000-0000-000000000040',1,'[]',false,gen_random_uuid())$$,'PT409','ROUTE_LOCKED','pedido congelado');
select is(public.reopen_preparation('71000000-0000-0000-0000-000000000030',2,'Conferir lista',gen_random_uuid())->>'status','draft','reabre');
select is((select eggs from public.stock_balances where location='farm'),300,'reabertura devolve');
select public.confirm_route_load('71000000-0000-0000-0000-000000000030',3,gen_random_uuid());
select public.record_payment('71000000-0000-0000-0000-000000000020',10000,now(),'pix',gen_random_uuid());
reset role;
insert into auth.users(id) values('71000000-0000-0000-0000-000000000003');
insert into public.profiles values('71000000-0000-0000-0000-000000000003','driver');
select set_config('request.jwt.claim.sub','71000000-0000-0000-0000-000000000003',true);
set local role authenticated;
select throws_ok($$select public.start_route('71000000-0000-0000-0000-000000000030',4,100,gen_random_uuid())$$,'42501','FORBIDDEN','motorista de outra rota negado');
select throws_ok($$select public.record_delivery('71000000-0000-0000-0000-000000000050','delivered',null,gen_random_uuid())$$,'42501','FORBIDDEN','outra atribuição não entrega');
select throws_ok($$select public.confirm_route_load('71000000-0000-0000-0000-000000000030',4,gen_random_uuid())$$,'42501','FORBIDDEN','motorista não prepara');
select set_config('request.jwt.claim.sub','71000000-0000-0000-0000-000000000002',true);
select is(public.start_route('71000000-0000-0000-0000-000000000030',4,100,gen_random_uuid())->>'status','in_progress','inicia');
select throws_ok($$select public.record_delivery('71000000-0000-0000-0000-000000000050','not_delivered',' ',gen_random_uuid())$$,'22023','REASON_REQUIRED','motivo obrigatório');
savepoint before_delivery;
reset role;
create function pg_temp.reject_sale() returns trigger language plpgsql as $$begin raise exception 'FIXTURE_FAILURE';end$$;
create trigger fixture_reject_sale before insert on public.sales for each row execute function pg_temp.reject_sale();
set local role authenticated;
select throws_ok($$select public.record_delivery('71000000-0000-0000-0000-000000000050','delivered',null,gen_random_uuid())$$,'P0001','FIXTURE_FAILURE','erro induzido aborta');
reset role;
select is((select eggs from public.stock_balances where route_id='71000000-0000-0000-0000-000000000030'),30,'rollback preserva ovos');
select is((select status from public.route_stops where id='71000000-0000-0000-0000-000000000050'),'pending','rollback preserva parada');
rollback to before_delivery;
select ok(public.record_delivery('71000000-0000-0000-0000-000000000050','delivered',null,'72000000-0000-0000-0000-000000000002')->>'saleId' is not null,'entrega cria venda');
select ok(public.record_delivery('71000000-0000-0000-0000-000000000050','delivered',null,gen_random_uuid())->>'saleId' is not null,'request novo não duplica');
select throws_ok($$select public.record_delivery('71000000-0000-0000-0000-000000000050','not_delivered','Ausente',gen_random_uuid())$$,'PT409','STOP_ALREADY_RESOLVED','resultado divergente');
select throws_ok($$select public.submit_route_return('71000000-0000-0000-0000-000000000030',99,0,0,null,gen_random_uuid())$$,'22023','INVALID_ODOMETER','km regressivo');
select is(public.submit_route_return('71000000-0000-0000-0000-000000000030',120,0,0,null,gen_random_uuid())->>'status','awaiting_reconciliation','aguarda dona');
select throws_ok($$select public.reconcile_route('71000000-0000-0000-0000-000000000030',7,0,0,null,gen_random_uuid())$$,'42501','FORBIDDEN','motorista não concilia');
select ok(not(public.get_driver_route('2091-01-02')::text ~ '(priceCents|costCents|creditCents|amountCents)'),'projeção motorista sem dinheiro');
select ok(not((public.reconcile_route_request('72000000-0000-0000-0000-000000000002','record_delivery')->'result') ? 'amountCents'),'recuperação motorista sem preço');
select throws_ok($$select private.consume_stock('71000000-0000-0000-0000-000000000030','sale',1,gen_random_uuid())$$,'42501',null,'helper privado negado');
select set_config('request.jwt.claim.sub','71000000-0000-0000-0000-000000000001',true);
select is((select count(*) from public.sales),1::bigint,'venda única');
select is((select amount_cents from public.sales),3300::bigint,'preço congelado');
select is((select cost_cents from public.sales),3000::bigint,'custo congelado');
select is(public.get_customer_account('71000000-0000-0000-0000-000000000020')->>'creditCents','6700','crédito aplicado');
select throws_ok($$select public.reconcile_route('71000000-0000-0000-0000-000000000030',(select version from public.route_runs where id='71000000-0000-0000-0000-000000000030'),1,0,'Conferido',gen_random_uuid())$$,'PT409','STOCK_MISMATCH','sobra divergente');

-- Empty vehicle still belongs to its active route until owner reconciliation.
reset role;
insert into public.route_runs(id,template_id,service_date,driver_id,vehicle_id) values('71000000-0000-0000-0000-000000000031','50000000-0000-0000-0000-000000000002','2091-01-03','71000000-0000-0000-0000-000000000002','71000000-0000-0000-0000-000000000010');
set local role authenticated;
select throws_ok($$select public.confirm_route_load('71000000-0000-0000-0000-000000000031',1,gen_random_uuid())$$,'PT409','VEHICLE_BUSY','veículo vazio ativo bloqueia outra rota');
select is(public.reconcile_route('71000000-0000-0000-0000-000000000030',(select version from public.route_runs where id='71000000-0000-0000-0000-000000000030'),0,0,null,'72000000-0000-0000-0000-000000000003')->>'status','closed','encerra');
select is(public.reconcile_route('71000000-0000-0000-0000-000000000030',7,0,0,null,'72000000-0000-0000-0000-000000000003')->>'status','closed','replay encerramento');
select ok(public.correct_sale_price((select id from public.sales where reversal_of is null and replacement_of is null),'[{"productId":"30000000-0000-0000-0000-000000000030","priceCents":3000}]','Preço errado',gen_random_uuid())->>'adjustmentId' is not null,'corrige preço');
select is((select eggs from public.stock_balances where location='farm'),270,'preço não retorna ovos');
select is(public.get_customer_account('71000000-0000-0000-0000-000000000020')->>'creditCents','7000','realoca crédito');
select throws_ok($$select public.correct_delivery_record('71000000-0000-0000-0000-000000000050','not_delivered',null,'Confirmação errada',gen_random_uuid())$$,'22023','GOODS_LOCATION_REQUIRED','local obrigatório');
select ok(public.correct_delivery_record('71000000-0000-0000-0000-000000000050','not_delivered','farm','Devolução integral conferida',gen_random_uuid())->>'correctionId' is not null,'compensa após fechar');
select is((select status from public.route_runs where id='71000000-0000-0000-0000-000000000030'),'closed','não reabre');
select is((select eggs from public.stock_balances where location='farm'),300,'devolve ovos');
select is(public.get_customer_account('71000000-0000-0000-0000-000000000020')->>'creditCents','10000','devolve crédito');
select throws_ok($$select public.correct_delivery_record('71000000-0000-0000-0000-000000000050','delivered','farm','Entrega tardia',gen_random_uuid())$$,'PT409','PHYSICAL_ADJUSTMENT_REQUIRED','fechada exige saída própria');
select is(public.reconcile_route_request('72000000-0000-0000-0000-000000000099','confirm_route_load')->>'status','closed','fecha tentativa');
select throws_ok($$select public.confirm_route_load('71000000-0000-0000-0000-000000000030',1,'72000000-0000-0000-0000-000000000099')$$,'55000','REQUEST_CLOSED','save atrasado bloqueado');
select throws_ok($$update public.route_runs set status='draft'$$,'42501',null,'escrita direta negada');

-- A second route exercises not-delivery, physical correction while in progress,
-- declared vs actual return, loss and rollback of a rejected reconciliation.
reset role;
insert into public.weekly_orders(id,customer_id,route_id,delivery_date,customer_name,customer_address) values
 ('71000000-0000-0000-0000-000000000041','71000000-0000-0000-0000-000000000020','71000000-0000-0000-0000-000000000031','2091-01-03','Cliente fictício','Rua fictícia');
insert into public.weekly_order_items values('71000000-0000-0000-0000-000000000041','30000000-0000-0000-0000-000000000030',30,2,3300);
insert into public.route_stops(id,route_id,order_id,kind,position,name) values('71000000-0000-0000-0000-000000000052','71000000-0000-0000-0000-000000000031','71000000-0000-0000-0000-000000000041','customer',1,'Cliente fictício');
insert into public.route_stops(id,route_id,kind,position,name) values('71000000-0000-0000-0000-000000000053','71000000-0000-0000-0000-000000000031','arrival',2,'Chegada');
set local role authenticated;
savepoint quantity_limit;
reset role;
update public.weekly_order_items set trays=2147483647 where order_id='71000000-0000-0000-0000-000000000041';
set local role authenticated;
select throws_ok($$select public.confirm_route_load('71000000-0000-0000-0000-000000000031',1,gen_random_uuid())$$,'22003','AMOUNT_OUT_OF_RANGE','ovos int32 antes do cast');
rollback to quantity_limit;
select public.confirm_route_load('71000000-0000-0000-0000-000000000031',1,gen_random_uuid());
select public.start_route('71000000-0000-0000-0000-000000000031',2,120,gen_random_uuid());
select public.record_delivery('71000000-0000-0000-0000-000000000052','not_delivered','Ausente',gen_random_uuid());
select is((select count(*) from public.sales where stop_id='71000000-0000-0000-0000-000000000052'),0::bigint,'não entrega não cria venda');
select public.correct_delivery_record('71000000-0000-0000-0000-000000000052','delivered','vehicle','Conferido integralmente',gen_random_uuid());
select is((select eggs from public.stock_balances where route_id='71000000-0000-0000-0000-000000000031'),0,'corrige para entregue com baixa real');
select public.correct_delivery_record('71000000-0000-0000-0000-000000000052','not_delivered','vehicle','Confirmação indevida',gen_random_uuid());
select is((select eggs from public.stock_balances where route_id='71000000-0000-0000-0000-000000000031'),60,'corrige para não entregue com retorno ao veículo');
select public.correct_delivery_record('71000000-0000-0000-0000-000000000052','delivered','vehicle','Conferido novamente',gen_random_uuid());
select public.correct_delivery_record('71000000-0000-0000-0000-000000000052','not_delivered','vehicle','Conferência final',gen_random_uuid());
select is((select eggs from public.stock_balances where route_id='71000000-0000-0000-0000-000000000031'),60,'ciclos de correção não duplicam ovos');
select is((select count(distinct reversal_of) from public.stock_events where route_id='71000000-0000-0000-0000-000000000031' and kind='adjustment'),2::bigint,'cada devolução reverte sua saída física');
select throws_ok($$select public.record_delivery('71000000-0000-0000-0000-000000000053','delivered',null,gen_random_uuid())$$,'22023','CUSTOMER_STOP_REQUIRED','operacional não gera venda');
select is(public.record_operational_stop('71000000-0000-0000-0000-000000000053',gen_random_uuid())->>'status','completed','checklist operacional');
select public.submit_route_return('71000000-0000-0000-0000-000000000031',130,59,1,'Quebra',gen_random_uuid());
select is((select eggs from public.stock_balances where location='farm'),240,'declaração não credita granja');
select throws_ok($$select public.reconcile_route('71000000-0000-0000-0000-000000000031',(select version from public.route_runs where id='71000000-0000-0000-0000-000000000031'),58,1,'Conferência',gen_random_uuid())$$,'PT409','STOCK_MISMATCH','divergência aborta sem saldo');
select public.reconcile_route('71000000-0000-0000-0000-000000000031',(select version from public.route_runs where id='71000000-0000-0000-0000-000000000031'),59,1,'Quebra conferida',gen_random_uuid());
select is((select eggs from public.stock_balances where location='farm'),299,'retorno e perda conciliados');
select is((select total_cost_cents from public.stock_balances where location='farm'),29900::bigint,'custo preservado');
select is((select eggs from public.stock_balances where route_id='71000000-0000-0000-0000-000000000031'),0,'carga esvaziada');
select is((select count(*) from public.stock_events where kind='loss' and route_id='71000000-0000-0000-0000-000000000031'),1::bigint,'perda única');
-- Collection route starts without a delivery load, generates no stock on return.
reset role;
insert into public.route_runs(id,template_id,service_date,driver_id,vehicle_id) values('71000000-0000-0000-0000-000000000032','50000000-0000-0000-0000-000000000001','2091-01-04','71000000-0000-0000-0000-000000000002','71000000-0000-0000-0000-000000000010');
set local role authenticated;
select is(public.start_route('71000000-0000-0000-0000-000000000032',1,130,gen_random_uuid())->>'status','in_progress','coleta sem carga');
select public.submit_route_return('71000000-0000-0000-0000-000000000032',150,0,0,null,gen_random_uuid());
select public.reconcile_route('71000000-0000-0000-0000-000000000032',3,0,0,null,gen_random_uuid());
select is((select eggs from public.stock_balances where location='farm'),299,'coleta não duplica compra');

-- Cancellation returns a ready load once and preserves the suspended order.
reset role;
insert into public.route_runs(id,template_id,service_date,driver_id,vehicle_id) values('71000000-0000-0000-0000-000000000033','50000000-0000-0000-0000-000000000002','2091-01-05','71000000-0000-0000-0000-000000000002','71000000-0000-0000-0000-000000000010');
insert into public.weekly_orders(id,customer_id,route_id,delivery_date,customer_name,customer_address) values('71000000-0000-0000-0000-000000000043','71000000-0000-0000-0000-000000000020','71000000-0000-0000-0000-000000000033','2091-01-05','Cliente fictício','Rua fictícia');
insert into public.weekly_order_items values('71000000-0000-0000-0000-000000000043','30000000-0000-0000-0000-000000000030',30,1,3300);
insert into public.route_stops(id,route_id,order_id,kind,position,name) values('71000000-0000-0000-0000-000000000054','71000000-0000-0000-0000-000000000033','71000000-0000-0000-0000-000000000043','customer',1,'Cliente fictício');
set local role authenticated;
select public.confirm_route_load('71000000-0000-0000-0000-000000000033',1,gen_random_uuid());
select is(public.cancel_route('71000000-0000-0000-0000-000000000033',2,'Viagem cancelada','72000000-0000-0000-0000-000000000010')->>'status','cancelled','cancela pronta');
select public.cancel_route('71000000-0000-0000-0000-000000000033',2,'Viagem cancelada','72000000-0000-0000-0000-000000000010');
select is((select eggs from public.stock_balances where location='farm'),299,'cancelamento retorna uma vez');
select is((select status from public.weekly_orders where id='71000000-0000-0000-0000-000000000043'),'suspended','pedido preservado suspenso');
select is((select count(*) from public.delivery_corrections where route_id='71000000-0000-0000-0000-000000000033' and kind='cancel'),1::bigint,'cancelamento tem trilha');
-- Unknown cost survives loading, selling and confirmed physical correction.
select public.record_stock_event(jsonb_build_object('kind','loss','location','farm','eggs',299,'effectiveAt',clock_timestamp(),'reason','Fixture esvaziamento'),gen_random_uuid());
select public.record_stock_event(jsonb_build_object('kind','adjustment','direction','in','location','farm','eggs',30,'effectiveAt',clock_timestamp(),'reason','Fixture custo desconhecido'),gen_random_uuid());
reset role;
insert into public.route_runs(id,template_id,service_date,driver_id,vehicle_id) values('71000000-0000-0000-0000-000000000034','50000000-0000-0000-0000-000000000002','2091-01-06','71000000-0000-0000-0000-000000000002','71000000-0000-0000-0000-000000000010');
insert into public.weekly_orders(id,customer_id,route_id,delivery_date,customer_name,customer_address) values('71000000-0000-0000-0000-000000000044','71000000-0000-0000-0000-000000000020','71000000-0000-0000-0000-000000000034','2091-01-06','Cliente fictício','Rua fictícia');
insert into public.weekly_order_items values('71000000-0000-0000-0000-000000000044','30000000-0000-0000-0000-000000000030',30,1,3300);
insert into public.route_stops(id,route_id,order_id,kind,position,name) values('71000000-0000-0000-0000-000000000055','71000000-0000-0000-0000-000000000034','71000000-0000-0000-0000-000000000044','customer',1,'Cliente fictício');
set local role authenticated;
select public.confirm_route_load('71000000-0000-0000-0000-000000000034',1,gen_random_uuid());
select public.start_route('71000000-0000-0000-0000-000000000034',2,150,gen_random_uuid());
select public.record_delivery('71000000-0000-0000-0000-000000000055','delivered',null,gen_random_uuid());
select is((select cost_cents from public.sales where stop_id='71000000-0000-0000-0000-000000000055'),null::bigint,'venda não inventa custo zero');
select public.correct_delivery_record('71000000-0000-0000-0000-000000000055','not_delivered','farm','Devolução conferida sem custo',gen_random_uuid());
select is((select total_cost_cents from public.stock_balances where location='farm'),null::bigint,'devolução desconhecida continua desconhecida');
select is((select cost_cents from public.sales where stop_id='71000000-0000-0000-0000-000000000055' and reversal_of is not null),null::bigint,'histórico sem recusteio');
select throws_ok($$select public.cancel_route('71000000-0000-0000-0000-000000000034',(select version from public.route_runs where id='71000000-0000-0000-0000-000000000034'),'Cancelar após saída',gen_random_uuid())$$,'PT409','ROUTE_LOCKED','não cancela em andamento');
select * from finish();
rollback;
